// Remplit les marques {nom} d'un texte traduit. Même convention que les entrées
// existantes ({client}, {deliveries}, {NAME}), mais utilisable avec plusieurs
// variables sans enchaîner les .replace().
const fill = (txt, vars) =>
  Object.keys(vars).reduce((acc, k) => acc.split('{' + k + '}').join(vars[k]), txt);

function tFor(lang) {
  return (key) => {
    const entry = TRANSLATIONS[key];
    if (!entry) return key;
    return entry[lang] || entry.fr || key;
  };
}

// Pour localiser un champ qui peut être soit string (FR par défaut), soit objet { fr, en, es }
function localizeField(field, lang) {
  if (field == null) return '';
  if (typeof field === 'object') return field[lang] || field.fr || '';
  return field;
}


