const BRIGITTE_TIER_MATRIX = {
  1: { bas: 2, std: 3, haut: 4 },  // Administrative
  2: { bas: 4, std: 5, haut: 6 },  // Comptable
  3: { bas: 5, std: 6, haut: 7 },  // Assistante de Direction
  4: { bas: 6, std: 7, haut: 7 },  // Légende : accès complet T7
};
const BRIGITTE_BONUS_MATRIX = {
  1: { bas: 0.10, std: 0.15, haut: 0.20 },
  2: { bas: 0.12, std: 0.18, haut: 0.25 },
  3: { bas: 0.15, std: 0.22, haut: 0.30 },
  4: { bas: 0.20, std: 0.27, haut: 0.35 }, // Légende : +5% par rapport au tier 3
};
function getBrigitteTierLevel(owned) {
  if (owned['brigitte_legende']) return 4;
  if (owned['brigitte_ad']) return 3;
  if (owned['brigitte_compta']) return 2;
  if (owned['autosell']) return 1;
  return 0;
}
function getBrigitteMaxContractTier(owned, salaryLevel, isGrumpy) {
  const tier = getBrigitteTierLevel(owned);
  if (tier === 0) return 1; // pas de Brigitte → contrats T1 accessibles en direct
  let maxTier = BRIGITTE_TIER_MATRIX[tier][salaryLevel] || 0;
  if (isGrumpy) maxTier = 1; // grève douce : plafond T1
  return maxTier;
}
// Rentabilité d'un contrat — €/minute basé sur cycle complet aller-retour
// Cycle ≈ 2 × deliveryTime (loading négligeable si stock plein)
// Notation ★ basée sur seuils absolus (€/min) pour permettre la comparaison
// cross-tier. Seuils calibrés sur la vraie plage des contrats (~100 à
// ~13 700 €/min) : sinon tout ce qui est ≥ T3 dépasserait l'ancien plafond
// (500) et afficherait 5★ partout. Répartition obtenue ≈ 15/14/15/28/28 %.
function getContractProfitability(c) {
  const cycleSec = c.deliveryTime * 2;
  const baseRevenue = c.qty * c.pricePerCube;
  const revenuePerMin = baseRevenue * 60 / cycleSec;
  const revenuePerSec = baseRevenue / cycleSec;
  let stars;
  if (revenuePerMin < 300) stars = 1;
  else if (revenuePerMin < 800) stars = 2;
  else if (revenuePerMin < 1800) stars = 3;
  else if (revenuePerMin < 3500) stars = 4;
  else stars = 5;
  return { cycleSec, baseRevenue, revenuePerMin, revenuePerSec, stars };
}

function getBrigitteEffectiveBonus(owned, salaryLevel, isGrumpy) {
  const tier = getBrigitteTierLevel(owned);
  if (tier === 0) return 0;
  const bonus = BRIGITTE_BONUS_MATRIX[tier][salaryLevel] || 0.15;
  return bonus * (isGrumpy ? 0.5 : 1);
}

// Durée du cycle de Fred selon son grade (en secondes)
// Plus le grade est élevé, plus son cycle est court (Fred opère plus de freezers en parallèle)
function getFredCycleDuration(tierId) {
  if (tierId === 'fred_dir') return 2;
  if (tierId === 'fred_chef') return 2.5;
  if (tierId === 'fred_perma') return 3;
  if (tierId === 'fred') return 4;
  if (tierId === 'fred_stage') return 4;
  return 0; // pas de Fred → pas de cycle
}

// Multiplicateur de prix « eau premium » — logique de REMPLACEMENT :
// on ne garde que le MEILLEUR palier possédé de chaque filière
// (la montée en gamme remplace le palier précédent, elle ne s'y ajoute
// pas). Provenance et Minéraux se cumulent entre eux (×). Max ≈ ×2.33.
function getPremiumWaterMult(owned) {
  // Provenance : meilleur palier EAU
  const prov = owned['eau_volcanique'] ? 1.50
    : owned['eau_source_montagne'] ? 1.30
    : owned['eau_source_filtree'] ? 1.15
    : 1;
  // Traitement : meilleur palier MINÉRAUX
  const mineral = owned['mineral_electrolytes'] ? 1.55
    : owned['mineral_oligo'] ? 1.30
    : owned['mineral_magnesium'] ? 1.15
    : 1;
  return prov * mineral;
}

function levelForXp(xp) {
  for (let i = LEVEL_THRESHOLDS.length - 1; i >= 0; i--) {
    if (xp >= LEVEL_THRESHOLDS[i]) return i + 1;
  }
  return 1;
}
function xpFromTotals(t, callsCount, owned) {
  // === NIVEAU = MATURITÉ RÉELLE DE L'ENTREPRISE ===
  // Moteur principal : le CA cumulé (moneyEarned). 1 € gagné ≈ 1 XP.
  // + bonus structurel : chaque amélioration achetée matérialise un
  //   investissement (« la boîte a grandi ») → +4000 XP / amélioration.
  // + jalons légers (production, contrats, appels) pour éviter un
  //   niveau plat en tout début de partie.
  const upgradeCount = owned ? Object.keys(owned).filter(k => owned[k]).length : 0;
  return Math.floor(
    (t.moneyEarned || 0) * 1.0
    + (t.produced || 0) * 0.05
    + (t.contractsCompleted || 0) * 200
    + (callsCount || 0) * 150
    + upgradeCount * 4000
  );
}

