// Demande dynamique — courbe sinusoidale lissée sur l'année
// Min ~0.55 au milieu de l'hiver, max ~2.5 au milieu de l'été
function getDynamicDemandMult(gameTime) {
  const yearProgress = (gameTime % (SEASON_DURATION * 4)) / (SEASON_DURATION * 4);
  const phase = 2 * Math.PI * (yearProgress - 5/8); // peak at 5/8 (milieu été)
  const cosVal = Math.cos(phase); // -1 to 1
  // Plancher hiver remonté à 0.7 (avant 0.55) : l'hiver garde un marché actif
  // pour éviter un temps mort de 2 min. L'été reste dominant à 2.5.
  return 1.6 + cosVal * 0.9; // → [0.7, 2.5]
}

// === COURBE SEASONNALE UNIFIÉE ===
// Une seule sinus pilote température / fonte / vitesse freeze / prod
// Peak mid-summer (yearProgress 5/8), trough mid-winter (1/8)
function getSeasonalCurve(gameTime) {
  const yearProgress = (gameTime % (SEASON_DURATION * 4)) / (SEASON_DURATION * 4);
  const phase = 2 * Math.PI * (yearProgress - 5/8);
  return Math.cos(phase); // -1 (mi-hiver) → 1 (mi-été)
}
function getDynamicTemp(gameTime) {
  return 16 + getSeasonalCurve(gameTime) * 14; // → [2°C, 30°C]
}
function getDynamicMeltMult(gameTime) {
  // Plancher hiver à 0.15 (avant 0) : la fonte ne tombe plus à zéro, ce qui
  // supprime le stockage gratuit infini et garde une légère pression toute
  // l'année. La prod hivernale (×1.2) reste très supérieure → on peut toujours
  // constituer un stock pour l'été, mais plus de thésaurisation sans risque.
  return Math.max(0.15, 0.875 + getSeasonalCurve(gameTime) * 0.725); // → [0.15, 1.6]
}
// Multiplicateur saisonnier sur le prix des contrats B2B et Retail.
// Demande forte en été → prix +25%. Hiver → prix −25%. Cohérent avec le marché spot.
function getDynamicContractMult(gameTime) {
  return 1.0 + getSeasonalCurve(gameTime) * 0.25; // → [0.75, 1.25]
}
function getDynamicFreezeMult(gameTime) {
  // Plus chaud = freeze plus lent. Hiver 0.86 (rapide), été 1.0 (normal)
  return 0.93 + getSeasonalCurve(gameTime) * 0.07;
}
function getDynamicProdMult(gameTime) {
  // Hiver = bonus prod (1.2), été = normal (1.0)
  return 1.1 - getSeasonalCurve(gameTime) * 0.1;
}

// Utilities (élec + eau + essence) — facture par saison
const UTIL_BASE_PER_FREEZER = 2;     // €/freezer/saison (avant 5 → −60%)
const UTIL_PROD_PER_GL = 0.015;      // €/glaçon produit (avant 0.048 → −69%)
const UTIL_FUEL_PER_GL_S = 0.0008;   // €/(GL × seconde de trajet) (avant 0.002 → −60%)

