function computeUtilitiesBill(freezerCount, seasonProd, seasonFuelCost, utilMult) {
  const base = freezerCount * UTIL_BASE_PER_FREEZER;
  const prodCost = seasonProd * UTIL_PROD_PER_GL;
  return Math.max(0, (base + prodCost) * utilMult + seasonFuelCost);
}
// Variante : retourne la ventilation détaillée des charges courantes en 3 postes.
// Permet à la modale RENTABILITÉ (P3) de montrer où passe l'argent.
function computeUtilitiesBreakdown(freezerCount, seasonProd, seasonFuelCost, utilMult) {
  const baseRaw = freezerCount * UTIL_BASE_PER_FREEZER;
  const prodCostRaw = seasonProd * UTIL_PROD_PER_GL;
  // utilMult ne s'applique pas au carburant (qui a déjà son propre calcul saisonnier).
  return {
    base: Math.max(0, baseRaw * utilMult),        // loyer & entretien (fixe)
    energy: Math.max(0, prodCostRaw * utilMult),  // énergie production (par GL)
    fuel: Math.max(0, seasonFuelCost),            // carburant transport
  };
}

