function TruckSvg({ qty = 20, meltAccum = 0, isLoaded = false, className = '' }) {
  // Cab pixel size is CONSTANT — only trailer length varies with qty
  let trailerW;
  if (qty < 30) trailerW = 9;
  else if (qty < 100) trailerW = 13;
  else if (qty < 300) trailerW = 18;
  else trailerW = 26;

  const cabW = 6;
  const gap = 1.5;
  const padding = 0.5;
  const vbH = 16;
  const vbW = trailerW + gap + cabW + padding * 2;

  const trailerY = 3;
  const trailerH = 8;
  const trailerX = padding;
  const cabX = trailerX + trailerW + gap;
  const cabY = trailerY;
  const cabH = trailerH;
  const wheelR = 1.2;
  const wheelY = vbH - 3.6;
  const pixelScale = 0.9;
  const meltClamped = Math.min(1, Math.max(0, meltAccum));
  const fillRatio = isLoaded ? 1 - meltClamped : 0;
  // Inner fill bar shrinks from the LEFT (back of trailer) as ice melts
  const fillW = trailerW * fillRatio;
  const fillX = trailerX + (trailerW - fillW);

  // Wheel positions under trailer
  const trailerWheels = [];
  if (qty < 300) {
    trailerWheels.push(trailerX + 1.4);
    trailerWheels.push(trailerX + trailerW - 1);
  } else {
    trailerWheels.push(trailerX + 1.4);
    trailerWheels.push(trailerX + trailerW / 2);
    trailerWheels.push(trailerX + trailerW - 1);
  }

  return (
    <svg
      width={vbW * pixelScale}
      height={vbH * pixelScale}
      viewBox={`0 0 ${vbW} ${vbH}`}
      className={className}
      style={{ display: 'block', overflow: 'visible' }}
    >
      {/* Remorque — contour seulement */}
      <rect
        x={trailerX} y={trailerY}
        width={trailerW} height={trailerH}
        fill="none"
        stroke="currentColor"
        strokeWidth="0.8"
      />

      {/* Niveau de remplissage (rétrécit par la gauche au fur et à mesure que ça fond) */}
      {isLoaded && fillRatio > 0 && (
        <rect
          x={fillX + 0.5} y={trailerY + 0.5}
          width={Math.max(0, fillW - 1)} height={trailerH - 1}
          fill="currentColor"
        />
      )}

      {/* Attelage entre remorque et tractor */}
      <line
        x1={trailerX + trailerW}
        y1={trailerY + trailerH - 1}
        x2={cabX}
        y2={cabY + cabH - 1}
        stroke="currentColor"
        strokeWidth="0.6"
      />

      {/* Tractor avec front arrondi */}
      <path
        d={`M ${cabX} ${cabY + cabH}
            L ${cabX} ${cabY + 1.3}
            Q ${cabX} ${cabY} ${cabX + 1} ${cabY}
            L ${cabX + cabW - 1.5} ${cabY}
            Q ${cabX + cabW} ${cabY} ${cabX + cabW} ${cabY + 1.8}
            L ${cabX + cabW} ${cabY + cabH}
            Z`}
        fill="var(--bg, white)"
        stroke="currentColor"
        strokeWidth="0.8"
      />

      {/* Pare-brise */}
      <path
        d={`M ${cabX + 0.8} ${cabY + 1.5}
            L ${cabX + cabW - 1.4} ${cabY + 1.5}
            L ${cabX + cabW - 0.3} ${cabY + 3}
            L ${cabX + 0.8} ${cabY + 3}
            Z`}
        fill="none"
        stroke="currentColor"
        strokeWidth="0.5"
      />

      {/* Roues remorque pleines */}
      {trailerWheels.map((wx, i) => (
        <circle key={i} cx={wx} cy={wheelY} r={wheelR} fill="currentColor" stroke="currentColor" strokeWidth="0.8" />
      ))}

      {/* Roue tractor pleine */}
      <circle cx={cabX + cabW * 0.55} cy={wheelY} r={wheelR} fill="currentColor" stroke="currentColor" strokeWidth="0.8" />

      {/* Gouttes derrière le camion (apparaissent quand la fonte > 5%) */}
      {isLoaded && meltClamped > 0.05 && (
        <>
          <circle cx={trailerX - 1.5} cy={vbH - 0.5} r={0.4} fill="currentColor" opacity={Math.min(1, meltClamped * 3)} />
          <circle cx={trailerX - 3} cy={vbH - 0.3} r={0.3} fill="currentColor" opacity={Math.min(1, meltClamped * 2.5)} />
          <circle cx={trailerX - 4.5} cy={vbH - 0.4} r={0.25} fill="currentColor" opacity={Math.min(1, meltClamped * 2)} />
        </>
      )}
    </svg>
  );
}


