// Prêt remboursé mensuellement. 24 mois = même durée réelle que les
// anciens 4 semestres (4 × 6 mois). Le nom de variable interne
// "semestersLeft" est conservé mais compte désormais des MOIS.
const LOAN_DURATION_SEMESTERS = 24; // 24 mois (= ancien 4 semestres)
const LOAN_OVERDUE_REP_LOSS = 20;
function getLoanTotalDue(loan) { return Math.round(loan.amount * (1 + loan.rate)); }

function getCampaignMultipliers(activeCampaign, gameTime, marketingMult, janiceGrumpy) {
  const out = { spotMult: 1, retailMult: 1, allMult: 1 };
  if (!activeCampaign) return out;
  if (gameTime > activeCampaign.endsAt) return out;
  const c = CAMPAIGNS_BY_ID[activeCampaign.id];
  if (!c) return out;
  // L'agence marketing est un prestataire payé : son efficacité ne dépend
  // plus d'un « moral » d'employée (mécanique Janice retirée). Seul le
  // multiplicateur marketing débloqué module l'effet des campagnes.
  const eff = marketingMult;
  // Table des effets PRIX par campagne (spot=vente directe, retail=contrats, all=les deux).
  // Avant, seules radio/influencers/tv appliquaient un effet ; les autres promettaient
  // un "Prix ×1.1x" sans jamais l'appliquer. Désormais cohérent.
  const PRICE_FX = {
    radio:            { kind: 'spot',   pct: 0.20 },
    stand_marche:     { kind: 'spot',   pct: 0.15 },
    influencers:      { kind: 'retail', pct: 0.10 },
    glamour_mag:      { kind: 'retail', pct: 0.15 },
    b2b_pro:          { kind: 'retail', pct: 0.12 },
    pub_en_ligne:     { kind: 'retail', pct: 0.10 },
    chef_etoile:      { kind: 'retail', pct: 0.18 },
    sponsoring_event: { kind: 'retail', pct: 0.12 },
    tv:               { kind: 'all',    pct: 0.15 },
    documentaire:     { kind: 'all',    pct: 0.12 },
    campagne_360:     { kind: 'all',    pct: 0.20 },
  };
  const fx = PRICE_FX[c.id];
  if (fx) {
    const m = 1 + (fx.pct * eff);
    if (fx.kind === 'spot') out.spotMult = m;
    else if (fx.kind === 'retail') out.retailMult = m;
    else out.allMult = m;
  }
  return out;
}

