function pickStatusMessage(ctx) {
  const r = arr => arr[Math.floor(Math.random() * arr.length)];

  // Priorité 1 : événements critiques
  if (ctx.atCap) return r(STATUS_POOLS.atCap);
  if (ctx.inOutage) return r(STATUS_POOLS.outage);
  if (ctx.inHeatwave) return r(STATUS_POOLS.heatwave);
  if (ctx.inDrought) return r(STATUS_POOLS.drought);
  if (ctx.inAutumnRush && ctx.seasonId === 'autumn') return r(STATUS_POOLS.autumnRush);

  // Priorité 2 : saison × stock (70% du temps)
  const stockTier = ctx.fillRatio < 0.30 ? 'low' : ctx.fillRatio < 0.75 ? 'mid' : 'high';
  const seasonKey = ctx.seasonId + '_' + stockTier;
  if (Math.random() < 0.70 && STATUS_POOLS[seasonKey]) {
    return r(STATUS_POOLS[seasonKey]);
  }

  // Priorité 3 : phase × niveau (grille recalée sur 50 niveaux)
  // Repères : fin P1≈15, début P3≈26, fin P3≈38, fin P4≈50.
  if (ctx.phase === 1) {
    if (ctx.level <= 6) return r(STATUS_POOLS.p1_early);
    if (ctx.level <= 11) return r(STATUS_POOLS.p1_mid);
    return r(STATUS_POOLS.p1_late);
  } else if (ctx.phase === 2) {
    if (ctx.level <= 19) return r(STATUS_POOLS.p2_early);
    if (ctx.level <= 22) return r(STATUS_POOLS.p2_mid);
    if (ctx.level <= 24) return r(STATUS_POOLS.p2_late);
    return r(STATUS_POOLS.p2_top);
  } else {
    if (ctx.level <= 30) return r(STATUS_POOLS.p3_early);
    if (ctx.level <= 34) return r(STATUS_POOLS.p3_mid);
    return r(STATUS_POOLS.p3_late);
  }
}

function computeStats(owned) {
  let s = {
    perClick: FREEZE_BASE_OUTPUT, meltMult: 1, sellMult: 1, passiveProd: 0,
    hasBrigitte: false, hasJanice: false, capBonus: 0,
    linesBonus: 0, truckMaxCap: 0, prodSpeedMult: 1, deliverySpeedMult: 1, deliveryBonus: 0,
    freezeDurationMult: 1, destructionMult: 1, truckColdMult: 1, coldInsurance: false,
    marketingMult: 1, utilityCostMult: 1,
    immunePneus: false, immuneAvis: false, immuneCyber: false, immuneFrigo: false,
  };
  for (const u of UPGRADES) {
    if (owned[u.id]) s = u.apply(s);
  }
  // === CAP DURS de fin de chaîne ===
  // Évite l'explosion exponentielle des multiplicateurs cumulés en endgame.
  // Cibles : revenus endgame ~150-200k€/mois, cumul partie ~3-5M€.
  s.sellMult = Math.min(s.sellMult, 25);
  s.prodSpeedMult = Math.min(s.prodSpeedMult, 20);
  // === NEW GAME+ : bonus de prestige permanent, APPLIQUÉ HORS PLAFOND ===
  // (Chaque Domination accumulée booste durablement vente et production.)
  if (PRESTIGE_RUNS > 0) {
    s.sellMult *= getPrestigeSellMult();
    s.prodSpeedMult *= getPrestigeProdMult();
  }
  return s;
}

// Séparateur de milliers : espace fine insécable (U+202F). Sa largeur ne vient
// pas de la police du texte mais de 'ThinSep', déclarée dans les styles, qui ne
// porte que ce caractère et lui donne une chasse fixe de 0,15 em. Le décalage
// est donc identique partout, quelle que soit la police de l'élément.
// Insécable par nature : un nombre ne se coupe jamais en fin de ligne.
const THIN_SEP = '\u202F';
// Ne groupe que la partie entière, pour ne pas découper les centimes.
// Sans effet sous 1000 : on peut donc en envelopper n'importe quel affichage
// numérique sans avoir à vérifier son ordre de grandeur au préalable.
const groupThousands = (str) => {
  const [intPart, decPart] = String(str).split(',');
  const grouped = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, THIN_SEP);
  return decPart != null ? grouped + ',' + decPart : grouped;
};
const fmtInt = n => groupThousands(String(Math.floor(n)));
// Montant au centime près. Groupe les milliers lui aussi : c'est ce format qui
// sert aux revenus et charges mensuels, qui dépassent vite le millier d'euros.
const fmt2 = n => groupThousands(n.toFixed(2).replace('.', ','));
// fmtK : format compact pour les gros chiffres principaux (stock, etc.).
// Précis sous 10 000, puis « k » (millier) et « M » (million) au-dessus.
// Ex : 9999 → "9 999", 10 000 → "10k", 12 345 → "12.3k", 1 500 000 → "1.5M".
// Séparateur décimal : point (pas de virgule) — plus lisible sur le gros chiffre.
const fmtK = n => {
  const abs = Math.abs(n);
  if (abs < 10000) return groupThousands(String(Math.floor(n)));
  if (abs < 1000000) return ((Math.round(n / 100) / 10).toLocaleString('fr-FR') + 'k').replace(/\s/g, '').replace(',', '.');
  return ((Math.round(n / 10000) / 100).toLocaleString('fr-FR') + 'M').replace(/\s/g, '').replace(',', '.');
};
// fmtCash : format compact pour le HUD principal — précis (centimes) sous 10k€, k€/M€ au-dessus.
const fmtCash = n => {
  const abs = Math.abs(n);
  if (abs < 10000) return groupThousands(n.toFixed(2).replace('.', ','));
  if (abs < 1000000) return (Math.round(n / 100) / 10).toLocaleString('fr-FR') + 'k';
  return (Math.round(n / 10000) / 100).toLocaleString('fr-FR') + 'M';
};

function niceThird(maxCap) {
  const n = maxCap / 3;
  if (n < 5) return Math.max(1, Math.round(n));
  if (n < 25) return Math.round(n / 5) * 5;
  if (n < 100) return Math.round(n / 25) * 25;
  if (n < 1000) return Math.round(n / 100) * 100;
  return Math.round(n / 500) * 500;
}

const TRUCK_IDS = ['camion_1', 'camion_2', 'camion_3', 'camion_4', 'camion_5', 'camion_6'];

function getLennyGrade(owned) {
  const count = TRUCK_IDS.filter(id => owned[id]).length;
  if (count === 0) return null;
  if (count === 1) return { count, name: { fr: 'Chauffeur',                en: 'Driver',                es: 'Chófer', zh: "司机", ru: "Водитель", it: "Autista", de: "Fahrer" },                salary: { bas: 42, std: 70, haut: 112 },     speedBonus: 0.05 };
  if (count === 2) return { count, name: { fr: 'Chef de tournée',          en: 'Route Manager',         es: 'Jefe de Ruta', zh: "路线经理", ru: "Менеджер маршрутов", it: "Responsabile Tratte", de: "Tourenleiter" },          salary: { bas: 135, std: 225, haut: 355 },     speedBonus: 0.10 };
  if (count === 3) return { count, name: { fr: 'Responsable logistique',  en: 'Logistics Lead',        es: 'Responsable de Logística', zh: "物流主管", ru: "Руководитель логистики", it: "Capo Logistica", de: "Logistikleiter" }, salary: { bas: 252, std: 420, haut: 672 },   speedBonus: 0.15 };
  return                    { count, name: { fr: 'Directeur Logistique',  en: 'Logistics Director',    es: 'Director de Logística', zh: "物流总监", ru: "Директор логистики", it: "Direttore Logistica", de: "Logistikdirektor" }, salary: { bas: 505, std: 840, haut: 1345 }, speedBonus: 0.20 };
}

