const randomLife = () => MARKET_MIN_LIFE + Math.random() * (MARKET_MAX_LIFE - MARKET_MIN_LIFE);

function makeInitialMarketplace(brigitteMaxTier, maxCap, truckMaxCap, notoriety, excludeIds = [], targetSize = null, currentPhase = 1, rejections = {}, currentGameTime = 0, owned = {}) {
  if (brigitteMaxTier === 0 || truckMaxCap === 0) return [];
  const eligible = B2B_CONTRACTS.filter(c =>
    c.brigitteTier <= brigitteMaxTier &&
    c.qty <= maxCap &&
    c.qty <= truckMaxCap &&
    (!c.notorietyMin || notoriety >= c.notorietyMin) &&
    !excludeIds.includes(c.id) &&
    !isContractInQuarantine(c.id, rejections, currentGameTime)
  );
  const target = targetSize != null ? targetSize : rollMarketTarget();
  // Phase 3+ : marketplace retail-only avec chance rare d'un gros B2B exceptionnel (tier 5+)
  if (currentPhase >= 3) {
    const retail = eligible.filter(c => c.archetype === 'RETAIL');
    const premiumB2B = eligible.filter(c => c.archetype !== 'RETAIL' && (c.brigitteTier || 0) >= 5);
    // Mid-tier (T3-4 non-retail) : réintégrés en P3 UNIQUEMENT s'ils sont réalisables
    // côté qualité — évite la "zone morte" où ces contrats n'apparaissaient nulle part.
    const midB2B = eligible.filter(c => c.archetype !== 'RETAIL'
      && (c.brigitteTier || 0) >= 3 && (c.brigitteTier || 0) < 5
      && isContractQualityFeasible(c, owned, 0));
    const result = [];
    const shuffledRetail = [...retail].sort(() => Math.random() - 0.5);
    const shuffledPremium = [...premiumB2B].sort(() => Math.random() - 0.5);
    const shuffledMid = [...midB2B].sort(() => Math.random() - 0.5);
    let premiumIdx = 0;
    let retailIdx = 0;
    let midIdx = 0;
    const slots = Math.min(target, MARKETPLACE_SIZE);
    for (let i = 0; i < slots; i++) {
      const r = Math.random();
      // 15% gros B2B prestige (T5+) · 15% mid-tier (T3-4 réalisables) · sinon retail
      if (premiumIdx < shuffledPremium.length && r < 0.15) {
        result.push({ contractId: shuffledPremium[premiumIdx].id, expiresIn: randomLife() });
        premiumIdx++;
      } else if (midIdx < shuffledMid.length && r < 0.30) {
        result.push({ contractId: shuffledMid[midIdx].id, expiresIn: randomLife() });
        midIdx++;
      } else if (retailIdx < shuffledRetail.length) {
        result.push({ contractId: shuffledRetail[retailIdx].id, expiresIn: randomLife() });
        retailIdx++;
      } else if (premiumIdx < shuffledPremium.length) {
        result.push({ contractId: shuffledPremium[premiumIdx].id, expiresIn: randomLife() });
        premiumIdx++;
      } else if (midIdx < shuffledMid.length) {
        result.push({ contractId: shuffledMid[midIdx].id, expiresIn: randomLife() });
        midIdx++;
      }
    }
    return result;
  }
  // Phase 1-2 : on ne propose QUE des contrats réalisables avec la qualité
  // actuelle. Les contrats exigeant de la qualité (PREMIUM/LUXE/RETAIL) sont
  // ainsi réservés à la Phase 3, quand les upgrades qualité existent.
  const feasible = eligible.filter(c => isContractQualityFeasible(c, owned, 0));
  const slots = Math.min(target, MARKETPLACE_SIZE);
  // Biais vers les contrats rémunérateurs (gros VOLUME / tier élevé) pour
  // densifier le revenu de la Phase 2 maintenant que le premium est verrouillé.
  const lucrative = feasible.filter(c => c.archetype === 'VOLUME' || (c.brigitteTier || 0) >= 3);
  const regular   = feasible.filter(c => !(c.archetype === 'VOLUME' || (c.brigitteTier || 0) >= 3));
  const shuffledLuc = [...lucrative].sort(() => Math.random() - 0.5);
  const shuffledReg = [...regular].sort(() => Math.random() - 0.5);
  const result = [];
  let li = 0, ri = 0;
  for (let i = 0; i < slots; i++) {
    const wantLucrative = Math.random() < 0.55; // ~55% des emplacements = contrat rémunérateur
    if (wantLucrative && li < shuffledLuc.length) {
      result.push({ contractId: shuffledLuc[li++].id, expiresIn: randomLife() });
    } else if (ri < shuffledReg.length) {
      result.push({ contractId: shuffledReg[ri++].id, expiresIn: randomLife() });
    } else if (li < shuffledLuc.length) {
      result.push({ contractId: shuffledLuc[li++].id, expiresIn: randomLife() });
    }
  }
  return result;
}

function repairCostFor(c) {
  return Math.round(c.qty * 2 + 100);
}

// ═══════════════════════════════════════════════════════════════════════
// SYSTÈME DE CONTRATS DYNAMIQUES
// Volume varie selon notoriété + qualité production.
// Joueur peut ajuster le prix ±20% avec impact sur volume/attente.
// Refus mémorisé : contrat refusé pour mauvais rapport Q/P → caché 3-5 saisons.
// ═══════════════════════════════════════════════════════════════════════

// === PROFILS QUALITÉ-PRIX par archetype ===
// qExpect = qualité attendue (0..1) ; priceTol = tolérance haut-prix (mult.)
// notoSensitivity = sensibilité volume à la notoriété (0..1) ; qualitySensitivity = idem qualité
const CONTRACT_ARCHETYPE_PROFILES = {
  LOCAL:    { qExpect: 0.30, priceTol: 1.10, notoSensitivity: 0.2, qualitySensitivity: 0.3,
              label: { fr: 'LOCAL', en: 'LOCAL', es: 'LOCAL', zh: "本地", ru: "ЛОКАЛЬНО", it: "LOCALE", de: "LOKAL" } },
  STANDARD: { qExpect: 0.50, priceTol: 1.15, notoSensitivity: 0.4, qualitySensitivity: 0.5,
              label: { fr: 'STANDARD', en: 'STANDARD', es: 'ESTÁNDAR', zh: "标准", ru: "СТАНДАРТ", it: "STANDARD", de: "STANDARD" } },
  PREMIUM:  { qExpect: 0.75, priceTol: 1.25, notoSensitivity: 0.6, qualitySensitivity: 0.8,
              label: { fr: 'PREMIUM', en: 'PREMIUM', es: 'PREMIUM', zh: "高端", ru: "ПРЕМИУМ", it: "PREMIUM", de: "PREMIUM" } },
  LUXE:     { qExpect: 0.90, priceTol: 1.40, notoSensitivity: 0.7, qualitySensitivity: 1.0,
              label: { fr: 'LUXE', en: 'LUXURY', es: 'LUJO', zh: "奢华", ru: "ЛЮКС", it: "LUSSO", de: "LUXUS" } },
  VOLUME:   { qExpect: 0.40, priceTol: 0.95, notoSensitivity: 0.8, qualitySensitivity: 0.3,
              label: { fr: 'VOLUME', en: 'VOLUME', es: 'VOLUMEN', zh: "批量", ru: "ОБЪЁМ", it: "VOLUME", de: "VOLUMEN" } },
  RETAIL:   { qExpect: 0.70, priceTol: 1.20, notoSensitivity: 0.9, qualitySensitivity: 0.7,
              label: { fr: 'RETAIL', en: 'RETAIL', es: 'RETAIL', zh: "零售", ru: "РИТЕЙЛ", it: "RETAIL", de: "EINZELHANDEL" } },
};
function getArchetypeProfile(c) {
  const a = c && c.archetype;
  return CONTRACT_ARCHETYPE_PROFILES[a] || CONTRACT_ARCHETYPE_PROFILES.STANDARD;
}

// === SCORE DE QUALITÉ DE PRODUCTION (0..1) ===
// Calculé à partir des upgrades qualité installées : provenance eau, enrichissement
// minéral, salles blanches, doseur précis, R&D. Chaque upgrade donne des points.
// IMPORTANT : un produit "standard" sans upgrade qualité a déjà une qualité de
// base de 0.25 (eau du robinet, freezer correct). Cela permet de signer les
// contrats LOCAL et VOLUME dès la P2 sans avoir investi dans la qualité.
const QUALITY_BASE = 0.25;
function computeQualityScore(owned) {
  if (!owned) return QUALITY_BASE;
  let points = 0;
  // Provenance eau : 0/15/35/55
  if (owned.eau_volcanique) points += 55;
  else if (owned.eau_source_montagne) points += 35;
  else if (owned.eau_source_filtree) points += 15;
  // Enrichissement minéral : 0/10/22/35
  if (owned.mineral_electrolytes) points += 35;
  else if (owned.mineral_oligo) points += 22;
  else if (owned.mineral_magnesium) points += 10;
  // Équipement qualité
  if (owned.salle_blanche_iso5) points += 25;
  else if (owned.salle_blanche_basique) points += 12;
  if (owned.doseur_precis) points += 8;
  if (owned.predictive_analytics) points += 7;
  if (owned.centre_rd) points += 15;
  // Score normalisé sur 100 puis ramené à 0..1, avec une base de 0.25.
  // Avec toutes les upgrades : 0.25 + 150/150 = 1.0
  let score = Math.min(1, QUALITY_BASE + points / 200);
  return score;
}

// Faisabilité qualité d'un contrat (le client refuse si la qualité est trop basse).
function isContractQualityFeasible(c, owned, slack = 0) {
  const prof = getArchetypeProfile(c);
  return computeQualityScore(owned) + slack >= (prof.qExpect - 0.15);
}

// === FIDÉLITÉ CLIENT ===
// Chaque fois qu'un contrat est honoré jusqu'au bout, le client devient plus fidèle.
// À la re-signature, il paie une prime : +8% par contrat honoré, plafonnée à +30%.
// (Récompense la relation longue avec un même client → boucle de fin de partie.)
function loyaltyPriceMult(completions) {
  return 1 + Math.min(0.30, (completions || 0) * 0.08);
}

// === DYNAMIQUE DU CONTRAT ===
// Renvoie un contrat enrichi avec qty/pricePerCube ajustés selon noto+qualité+priceAdjust.
// priceAdjust : multiplicateur de prix entre 0.8 (−20%) et 1.2 (+20%), défaut 1.0.
function applyContractDynamics(c, owned, notoriety, priceAdjust = 1.0) {
  if (!c) return null;
  const prof = getArchetypeProfile(c);
  const quality = computeQualityScore(owned);
  const notoFactor01 = Math.min(1, (notoriety || 0) / 100);

  // === Volume ===
  // Base volume modulée par noto + qualité, puis par l'ajustement prix.
  const notoMult = 1 + prof.notoSensitivity * (notoFactor01 - 0.3); // neutre à 30% noto
  const qualityMult = 1 + prof.qualitySensitivity * (quality - prof.qExpect); // négatif si qualité insuffisante
  // Ajustement prix : +X% prix → −1.5X% volume ; −X% prix → +1.25X% volume
  const priceDelta = priceAdjust - 1;
  const priceVolumeMult = priceDelta >= 0
    ? Math.max(0.4, 1 - priceDelta * 1.5)   // hausse prix = baisse volume forte
    : Math.min(1.4, 1 - priceDelta * 1.25); // baisse prix = hausse volume modérée

  const dynQty = Math.max(1, Math.round(c.qty * notoMult * qualityMult * priceVolumeMult));
  const dynPrice = c.pricePerCube * priceAdjust;

  // === Qualité/Prix acceptable ? ===
  // priceAdjust > priceTol → client refuse (trop cher)
  // quality < qExpect − 0.15 → client n'accepte plus (qualité trop basse)
  const priceTooHigh = priceAdjust > prof.priceTol;
  const qualityTooLow = quality < (prof.qExpect - 0.15);
  const ratioOk = !priceTooHigh && !qualityTooLow;

  return {
    ...c,
    qty: dynQty,
    pricePerCube: dynPrice,
    _baseQty: c.qty,
    _basePricePerCube: c.pricePerCube,
    _priceAdjust: priceAdjust,
    _qualityScore: quality,
    _qExpect: prof.qExpect,
    _archetypeProfile: prof,
    _ratioOk: ratioOk,
    _priceTooHigh: priceTooHigh,
    _qualityTooLow: qualityTooLow,
  };
}

// === DISPONIBILITÉ D'UN CONTRAT (UI marketplace) ===
// Renvoie tous les blocages d'un contrat enrichi par applyContractDynamics().
// Utilisé pour griser la carte ET afficher la raison directement, sans
// que le joueur ait à cliquer pour découvrir le blocage.
//   ctx = { noSlot, reputation, segments: {famille, jeunesse, pro, luxe, eco} }
function getContractAvailability(c, ctx) {
  const reasons = [];
  // 1) Slot camion
  if (ctx.noSlot) {
    reasons.push({
      key: 'no_slot',
      label: { fr: 'Aucun camion libre', en: 'No truck available', es: 'Sin camión libre', zh: '无可用卡车', ru: 'Нет свободного грузовика', it: 'Nessun camion libero', de: 'Kein freier LKW' },
      hint:  { fr: 'Libère un slot ou achète un palier Lenny', en: 'Free a slot or buy a Lenny tier', es: 'Libera un espacio o compra un nivel Lenny', zh: '释放一个位或购买莱尼等级', ru: 'Освободите слот или купите уровень Ленни', it: 'Libera uno slot o compra un livello Lenny', de: 'Slot freigeben oder Lenny-Stufe kaufen' },
    });
  }
  // 2) Réputation
  if (ctx.reputation < 20) {
    reasons.push({
      key: 'low_rep',
      label: { fr: 'Réputation trop basse', en: 'Reputation too low', es: 'Reputación demasiado baja', zh: '声誉太低', ru: 'Слишком низкая репутация', it: 'Reputazione troppo bassa', de: 'Ruf zu niedrig' },
      hint:  { fr: `Réputation ${Math.round(ctx.reputation)} / 20 mini`, en: `Reputation ${Math.round(ctx.reputation)} / 20 min`, es: `Reputación ${Math.round(ctx.reputation)} / 20 mín`, zh: `声誉 ${Math.round(ctx.reputation)} / 最低 20`, ru: `Репутация ${Math.round(ctx.reputation)} / мин 20`, it: `Reputazione ${Math.round(ctx.reputation)} / min 20`, de: `Ruf ${Math.round(ctx.reputation)} / min 20` },
    });
  }
  // 3) Qualité
  if (c._qualityTooLow) {
    const cur = Math.round((c._qualityScore || 0) * 100);
    const req = Math.round(((c._qExpect || 0) - 0.15) * 100); // seuil réel
    reasons.push({
      key: 'low_quality',
      label: { fr: 'Qualité insuffisante', en: 'Quality too low', es: 'Calidad insuficiente', zh: '质量不足', ru: 'Низкое качество', it: 'Qualità insufficiente', de: 'Qualität zu niedrig' },
      hint:  { fr: `Qualité ${cur}/100 · client veut ${req}+`, en: `Quality ${cur}/100 · client wants ${req}+`, es: `Calidad ${cur}/100 · cliente quiere ${req}+`, zh: `品质 ${cur}/100 · 客户要 ${req}+`, ru: `Качество ${cur}/100 · клиент хочет ${req}+`, it: `Qualità ${cur}/100 · cliente vuole ${req}+`, de: `Qualität ${cur}/100 · Kunde will ${req}+` },
    });
  }
  // 4) Segment (P3+)
  if (c.targetSegment && c.minSegment && ctx.segments) {
    const segVal = ctx.segments[c.targetSegment];
    if (typeof segVal === 'number' && segVal < c.minSegment) {
      reasons.push({
        key: 'low_segment',
        label: { fr: 'Segment trop faible', en: 'Segment too low', es: 'Segmento demasiado bajo', zh: '细分市场太低', ru: 'Сегмент слишком слабый', it: 'Segmento troppo basso', de: 'Segment zu niedrig' },
        hint:  { fr: `${c.targetSegment} ${Math.round(segVal)} / ${c.minSegment}`, en: `${c.targetSegment} ${Math.round(segVal)} / ${c.minSegment}`, es: `${c.targetSegment} ${Math.round(segVal)} / ${c.minSegment}`, zh: `${c.targetSegment} ${Math.round(segVal)} / ${c.minSegment}`, ru: `${c.targetSegment} ${Math.round(segVal)} / ${c.minSegment}`, it: `${c.targetSegment} ${Math.round(segVal)} / ${c.minSegment}`, de: `${c.targetSegment} ${Math.round(segVal)} / ${c.minSegment}` },
      });
    }
  }
  return { available: reasons.length === 0, reasons };
}

// === MÉMORISATION DES REFUS QUALITÉ/PRIX ===
// Quand un contrat est refusé (par le client) pour mauvais ratio Q/P,
// il est mis en quarantaine : il ne réapparaîtra pas dans la marketplace
// pendant N saisons (3-5 selon archetype).
const REJECTION_QUARANTINE_SEASONS = {
  LOCAL: 2, STANDARD: 3, PREMIUM: 4, LUXE: 5, VOLUME: 3, RETAIL: 4,
};
function getRejectionQuarantine(c) {
  const a = c && c.archetype;
  return REJECTION_QUARANTINE_SEASONS[a] || 3;
}
// Convertit "saisons" en durée gameTime (1 saison = SEASON_DURATION secondes)
function isContractInQuarantine(contractId, rejections, currentGameTime) {
  if (!rejections || !rejections[contractId]) return false;
  const r = rejections[contractId];
  const elapsed = currentGameTime - r.rejectedAt;
  const duration = r.quarantineSeasons * SEASON_DURATION;
  return elapsed < duration;
}

// Phase 2+ — Profil d'un contrat : nombre de livraisons attendues + temps total alloué.
// Le contrat se termine après maxDeliveries livraisons réussies (= proposition de renouvellement).
// Si globalDeadlineSec expire avant → échec (pénalité réputation, pas de bonus).
//
// La deadline est calculée sur du réel : (cycle aller-retour × nombre de livraisons) × marge.
// CALIBRATION VOULUE :
//   - Sprints (tier élevé) : marge SERRÉE voire NÉGATIVE → impossible sans boost. Force à booster.
//   - Marathons (tier bas, retail) : marge GÉNÉREUSE → absorbe les aléas longue durée (pannes, pauses).
function getContractProfile(c) {
  if (!c) return { maxDeliveries: 1, globalDeadlineSec: 999999, completionBonusPct: 0 };
  const dt = c.deliveryTime || 60;
  let maxDeliveries, margin, completionBonusPct;
  if (c.archetype === 'RETAIL') {
    if (c.notorietyMin >= 70) { maxDeliveries = 25; margin = 1.35; completionBonusPct = 0.18; } // marathon long → marge ample
    else if (c.notorietyMin >= 50) { maxDeliveries = 20; margin = 1.30; completionBonusPct = 0.15; }
    else { maxDeliveries = 15; margin = 1.25; completionBonusPct = 0.12; }
  } else {
    const tier = c.brigitteTier || 1;
    if (tier >= 5) { maxDeliveries = 3; margin = 0.95; completionBonusPct = 0.25; }            // sprint : -5% → BOOST OBLIGATOIRE
    else if (tier >= 4) { maxDeliveries = 5; margin = 0.98; completionBonusPct = 0.20; }       // court tendu : -2% → boosts indispensables
    else if (tier >= 3) { maxDeliveries = 8; margin = 1.08; completionBonusPct = 0.15; }       // standard : 8% pour 1 pépin
    else { maxDeliveries = 12; margin = 1.20; completionBonusPct = 0.10; }                     // marathon doux : confortable
  }
  // === MULTIPLICATEUR DELIVERIES SELON CATÉGORIE ===
  // Mai 2026 : on multiplie le nombre d'aller-retours d'un contrat selon sa catégorie
  // pour éviter la surproduction de stock en P2/P3.
  // Logique : petits contrats = longs et réguliers ; gros = courts mais juteux.
  // Le total revenu reste équilibré : T1 ×8 × petit montant ≈ T3 ×3 × gros montant.
  if (c.archetype !== 'RETAIL') {
    const tier = c.brigitteTier || 1;
    let multiplier;
    if (tier <= 2) multiplier = 8;       // T1 catégorie (bars, brasseries, snacks) → 8× plus long
    else if (tier <= 4) multiplier = 5;  // T2 catégorie (pizzerias, salons, restos) → 5× plus long
    else multiplier = 3;                  // T3 catégorie (gros, prestige) → 3× plus long (déjà court à la base)
    maxDeliveries = maxDeliveries * multiplier;
  }
  // Plafond raisonnable : tout contrat dépassant 40 livraisons est divisé par
  // 2 (les marathons de 96 trajets T1-T2 deviennent ~48, plus jouable).
  if (maxDeliveries > 40) maxDeliveries = Math.ceil(maxDeliveries / 2);
  // Cycle aller-retour réel + overhead pause moyen (8s tous les ~4 trajets ≈ +2s/trajet)
  const cycleSec = dt * 2 + 2;
  const baseTotalSec = cycleSec * maxDeliveries;
  const globalDeadlineSec = Math.round(baseTotalSec * margin);
  return { maxDeliveries, globalDeadlineSec, completionBonusPct };
}

// === Indicateur d'alerte hors-écran ===
// Scanne les éléments marqués [data-alert] (appel entrant, incident
// véhicule, action RH, sabotage actif…). Pour chacun qui est au-dessus
// ou en-dessous du viewport, affiche une petite flèche sticky :
//  - collée en HAUT (▲) si l'élément est plus haut, en BAS (▼) si plus bas
//  - alignée horizontalement sur le CENTRE X de l'élément concerné
//    → en scrollant on tombe pile sur la zone à traiter
//  - cliquable : scrolle directement vers l'élément
// Plusieurs alertes simultanées → plusieurs flèches (une par élément).
function ScrollAlert() {
  const [arrows, setArrows] = useState([]);

  useEffect(() => {
    let raf = 0;
    const ICONS = {
      phone: '\u2755',     // ❕ alerte générique (appel, contrat, action…)
      vehicle: '\u26A0',   // ⚠ panne / pneu crevé
      rh: '\u25C9',        // ◉ action RH / incident social
      sabotage: '\u26A1',  // ⚡ sabotage actif
    };
    const LABEL = {
      phone: 'APPEL', vehicle: 'VÉHICULE', rh: 'RH', sabotage: 'ALERTE',
    };
    const scan = () => {
      const vh = window.innerHeight || document.documentElement.clientHeight;
      const vw = window.innerWidth || document.documentElement.clientWidth;
      const els = document.querySelectorAll('[data-alert]');
      const next = [];
      const seen = new Set();
      els.forEach((el) => {
        const r = el.getBoundingClientRect();
        if (r.width === 0 && r.height === 0) return; // non rendu
        const kind = el.getAttribute('data-alert') || 'phone';
        // dé-doublonne par type+position pour éviter les flèches superposées
        let dir = null;
        if (r.bottom < 56) dir = 'up';          // entièrement au-dessus
        else if (r.top > vh - 56) dir = 'down'; // entièrement en-dessous
        if (!dir) return;                       // visible → pas de flèche
        // centre X de l'élément, borné pour rester à l'écran
        let cx = r.left + r.width / 2;
        cx = Math.max(34, Math.min(vw - 34, cx));
        const key = kind + ':' + dir + ':' + Math.round(cx / 24);
        if (seen.has(key)) return;
        seen.add(key);
        next.push({ key, kind, dir, x: cx, el });
      });
      setArrows(prev => {
        // évite un re-render si rien n'a changé (perf)
        if (prev.length === next.length &&
            prev.every((p, i) => p.key === next[i].key && Math.abs(p.x - next[i].x) < 2)) {
          return prev;
        }
        return next;
      });
      raf = requestAnimationFrame(scan);
    };
    raf = requestAnimationFrame(scan);
    return () => cancelAnimationFrame(raf);
  }, []);

  if (arrows.length === 0) return null;

  const goTo = (el) => {
    try { el.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch (e) { /* noop */ }
  };

  return (
    <>
      {arrows.map(a => {
        const LABEL = { phone: 'APPEL', vehicle: 'VÉHICULE', rh: 'RH', sabotage: 'ALERTE' };
        return (
          <button
            key={a.key}
            className={`scroll-alert scroll-alert-${a.dir}`}
            style={{ left: a.x + 'px' }}
            onClick={() => goTo(a.el)}
            aria-label={LABEL[a.kind] || 'ALERTE'}
          >
            <span className="sa-arrow">{a.dir === 'up' ? '\u25B2' : '\u25BC'}</span>
            <span className="sa-tri" aria-hidden="true"><span className="sa-tri-bang">!</span></span>
          </button>
        );
      })}
    </>
  );
}

