  // Helper : agrège tous les effets actifs en un seul objet
  const aggregateFrictionEffects = (frictions, gameT) => {
    const agg = {
      prodBlock: false, prodMult: 1, meltMult: 1, capMult: 1,
      directDemMult: 1, b2bDemMult: 1, truckSpeedMult: 1, fuelMult: 1,
      blockTrucks: false, blockCalls: false, blockMarket: false,
      blockMarketing: false, blockUpgrades: false, pauseBrigitte: false,
      disablePremium: false,
    };
    for (const k in frictions) {
      const f = frictions[k];
      if (!f || f.expiresAt <= gameT) continue;
      const e = f.effects || {};
      if (e.prodBlock) agg.prodBlock = true;
      if (typeof e.prodMult === 'number') agg.prodMult *= e.prodMult;
      if (typeof e.meltMult === 'number') agg.meltMult *= e.meltMult;
      if (typeof e.capMult === 'number') agg.capMult *= e.capMult;
      if (typeof e.directDemMult === 'number') agg.directDemMult *= e.directDemMult;
      if (typeof e.b2bDemMult === 'number') agg.b2bDemMult *= e.b2bDemMult;
      if (typeof e.truckSpeedMult === 'number') agg.truckSpeedMult *= e.truckSpeedMult;
      if (typeof e.fuelMult === 'number') agg.fuelMult *= e.fuelMult;
      if (e.blockTrucks) agg.blockTrucks = true;
      if (e.blockCalls) agg.blockCalls = true;
      if (e.blockMarket) agg.blockMarket = true;
      if (e.blockMarketing) agg.blockMarketing = true;
      if (e.blockUpgrades) agg.blockUpgrades = true;
      if (e.pauseBrigitte) agg.pauseBrigitte = true;
      if (e.disablePremium) agg.disablePremium = true;
    }
    return agg;
  };
