  // Mesure dynamique de la position du trait sous le header pour ancrer les notifications
  useEffect(() => {
    const measure = () => {
      if (!hdrRef.current) return;
      let top = 0;
      let cur = hdrRef.current;
      while (cur) {
        top += cur.offsetTop;
        cur = cur.offsetParent;
      }
      const lineY = top + hdrRef.current.offsetHeight;
      document.documentElement.style.setProperty('--notif-line-y', `${lineY}px`);
    };
    measure();
    window.addEventListener('resize', measure);
    const t1 = setTimeout(measure, 100);
    const t2 = setTimeout(measure, 500); // re-measure after fonts/layout settle
    return () => {
      window.removeEventListener('resize', measure);
      clearTimeout(t1);
      clearTimeout(t2);
    };
  }, [phase]); // re-measure when phase changes (header content can shift)
  const sellThresholdRef = useRef(0.30);
